// Generated from world/guest_cast.py. Shared names, art direction and voice.
export const GUEST_CAST={"friend:marco":{"id":"friend:marco","name":"Marco","archetype":"adventurous","species":"duck","shape":"pear","head":"longbill","palette":["#c49c75","#c5bda0","#d9805f"],"gear":["hat_cowboy","bandana"],"prop":"compass","habit":"Stops to tap a compass, then confidently points the wrong way.","bio":"A mud-booted pathfinder with an enormous bill, a patched bag and spectacularly unreliable confidence.","height":88,"pace":3.7,"social":0.45,"radius":18,"voice":{"greeting":"Cheese! Excellent. A local. Which way is north today?","returning":"Found you again. Deliberately, this time. Mostly.","opening":"I name every path I discover. This one is Marco Was Here Twice.","main":"The compass says north. My stomach says bakery. A difficult scientific disagreement.","story":"I once led an expedition straight back to its own picnic. Morale was exceptional.","personal":"Getting lost is fine. Being lost without someone to tell about it is the rotten part.","activity":"Come on, Cheese. We will take the scenic route, then admit it was an accident.","gift":"For me? I will put it somewhere safe. I have a map of my safe places.","farewell":"Onward! If I come past again, pretend that was the plan."},"rare":false},"friend:amelia":{"id":"friend:amelia","name":"Amelia","archetype":"adventurous","species":"duck","shape":"runner","head":"swept","palette":["#b7c6cf","#e4d8bb","#d46b58"],"gear":["sunglasses_aviator","scarf_red"],"prop":"plane","habit":"Squints into the wind, tests a paper glider, and catches it with her wing.","bio":"A lean silver runner with swept-back feathers; a fearless pilot who gets airsick on swings.","height":91,"pace":4.6,"social":0.45,"radius":19,"voice":{"greeting":"Wind good. Visibility good. Landing dignity: we will see.","returning":"Your pond looks lovely from above. Also extremely wet from below.","opening":"I am testing a paper glider. The paper thinks it is a boat.","main":"Everyone asks about the flying. Nobody asks about the very important falling-with-intent.","story":"My first solo flight ended in a laundry basket. Five stars for the landing surface.","personal":"I keep every failed glider. They tried something difficult. So did I.","activity":"Be my ground crew? Your job is to shout when the tree gets close.","gift":"Oh! That belongs in the lucky pocket, beside the emergency biscuit.","farewell":"Clear skies, Cheese. And forgiving bushes."},"rare":false},"friend:columbus":{"id":"friend:columbus","name":"Columbus","archetype":"adventurous","species":"duck","shape":"barrel","head":"brow","palette":["#bba77f","#788f87","#cf9563"],"gear":["hat_pirate"],"prop":"map","habit":"Unfolds a map upside down and rotates himself instead of the paper.","bio":"A broad, weather-beaten navigator with a severe brow and a deeply unserious sense of direction.","height":84,"pace":3.1,"social":0.45,"radius":14,"voice":{"greeting":"I have charted this pond. Unfortunately the ink was water-soluble.","returning":"Ah, familiar shores. Familiar suspicious rock. Familiar Cheese.","opening":"The blank bit on my map is either a mystery or where I spilled soup.","main":"Never trust a map with no coffee stains. It has not been anywhere.","story":"A snail once overtook my expedition. We made it our guide.","personal":"I like returning to places more than discovering them. You can tell who missed you.","activity":"Help me name that inlet. No, we already have three Little Shits Creek.","gift":"A fine addition to the ship. The ship is currently a bucket.","farewell":"I sail at dawn. Unless the bucket leaks again."},"rare":false},"friend:vasco":{"id":"friend:vasco","name":"Vasco","archetype":"adventurous","species":"duck","shape":"low","head":"sleepy","palette":["#8ba6aa","#d3b894","#8cae76"],"gear":["sun_hat"],"prop":"flask","habit":"Takes a tiny thermos break after every perfectly manageable journey.","bio":"A low, long-bodied wanderer who treats a five-step stroll like a luxurious expedition.","height":68,"pace":2.4,"social":0.45,"radius":8,"voice":{"greeting":"Made it all the way here. Right, tea break.","returning":"Same lovely pond. Same excellent place to sit down.","opening":"My travel journal has four pages about this bench.","main":"An adventure needs danger, discovery, and somewhere sensible to put a cup.","story":"Crossed a desert once. A sandbox, technically. I still rationed the biscuits.","personal":"People rush past lovely things. I am helping by being quite difficult to rush.","activity":"Fancy an expedition to that patch of shade? We can stop halfway.","gift":"You packed for me? That is a very advanced form of friendship.","farewell":"Safe travels. Or safe sitting. Equally respectable."},"rare":false},"friend:marina":{"id":"friend:marina","name":"Marina","archetype":"adventurous","species":"duck","shape":"teardrop","head":"bob","palette":["#789dae","#d9cabc","#edba82"],"gear":["scarf_striped"],"prop":"shell","habit":"Listens to a shell, taps a rhythm with one foot, and answers it quietly.","bio":"A sleek blue shore duck with a blunt feather bob and a pocket full of imaginary sea reports.","height":78,"pace":3.8,"social":0.45,"radius":17,"voice":{"greeting":"The tide sent me. Well, a puddle did. Same department.","returning":"Cheese! I brought news from the other side of the water. More water.","opening":"This shell sounds like the sea. This one sounds like a very rude kettle.","main":"I collect shorelines. Difficult to carry home, but the pockets are free.","story":"I wrote a message in a bottle. It returned with a complaint about my handwriting.","personal":"Sometimes I listen to empty shells just to have someone listen back.","activity":"Walk the bank with me? We can judge the interesting stones.","gift":"Oh, this one has a story. I can tell. I will make one up if necessary.","farewell":"See you when the water changes its mind."},"rare":false},"friend:einstein":{"id":"friend:einstein","name":"Einstein","archetype":"scholarly","species":"duck","shape":"shaggy","head":"tuft","palette":["#b4acb8","#e1dfcd","#c5a0d8"],"gear":["glasses_nerd"],"prop":"chalkboard","habit":"Chalks an equation, squints, then rubs out everything except the duck doodle.","bio":"A frazzled, round professor with a storm of pale feathers and chalk on every available surface.","height":83,"pace":3.2,"social":0.45,"radius":9,"voice":{"greeting":"Cheese! Quick question. How many crumbs make a philosophical problem?","returning":"I solved our last problem. Then found three smaller problems inside it.","opening":"My feathers are not messy. They are expressing several competing hypotheses.","main":"Time is relative. Especially the five minutes before lunch.","story":"I proved I had lost my glasses while looking directly through them.","personal":"I like being wrong around you. You make it less of a catastrophe.","activity":"Stand there a moment. I need a control duck.","gift":"Fascinating! I shall label it before I forget why I love it.","farewell":"Must dash. An idea is escaping through a hole in my attention."},"rare":false},"friend:newton":{"id":"friend:newton","name":"Newton","archetype":"scholarly","species":"duck","shape":"pear","head":"small","palette":["#b48d6d","#c7c0a1","#aab871"],"gear":["hat_beanie"],"prop":"apple","habit":"Balances an apple on his head, looks proud, and catches the inevitable result.","bio":"A bottom-heavy little thinker with a tiny head and the air of someone arguing with gravity.","height":75,"pace":3.5,"social":0.45,"radius":10,"voice":{"greeting":"Do you know why things fall, Cheese? I have several bruised opinions.","returning":"Still here? Excellent. A stable reference point.","opening":"This apple is essential equipment. It is also getting a bit pecked.","main":"The universe has rules. The apple refuses to explain them.","story":"My greatest experiment was ruined by an experimental snack.","personal":"It is nice when someone stays to hear the explanation, even the terrible one.","activity":"Catch this. For science. And because I am out of apples.","gift":"Thank you! I promise not to drop it until I have measured it.","farewell":"I must go. Something is about to fall somewhere."},"rare":false},"friend:ada":{"id":"friend:ada","name":"Ada","archetype":"scholarly","species":"duck","shape":"runner","head":"bob","palette":["#7d9f9d","#e0c6a1","#d68b88"],"gear":["bow_tie_blue"],"prop":"abacus","habit":"Slides abacus beads in a precise pattern and smiles at one deliberately wrong bead.","bio":"A neat teal runner with a square bob, striped cuffs and a soft spot for gloriously useless inventions.","height":81,"pace":4,"social":0.45,"radius":11,"voice":{"greeting":"Hello, Cheese. I made a machine that counts hellos. That was one.","returning":"Welcome back to the sequence. You are my favorite recurring event.","opening":"I taught my abacus a joke. It is still calculating the timing.","main":"A bug is just a feature with a very bad alibi.","story":"I automated my morning routine. Now I have spare time to repair my morning routine.","personal":"People think precise means cold. I remember how everyone takes their tea.","activity":"Help me test this pattern? There are absolutely no explosions scheduled.","gift":"You remembered! That is much nicer than a perfect calculation.","farewell":"Until next iteration, Cheese. That means see you soon."},"rare":false},"friend:darwin":{"id":"friend:darwin","name":"Darwin","archetype":"scholarly","species":"duck","shape":"barrel","head":"longbill","palette":["#9eaa77","#d6c4a1","#cfaa70"],"gear":["hat_cowboy"],"prop":"magnifier","habit":"Studies a beetle through a magnifier, then apologizes for staring.","bio":"A mossy, broad-backed naturalist whose bill and pockets are both much larger than necessary.","height":87,"pace":2.8,"social":0.45,"radius":13,"voice":{"greeting":"Shh. That beetle is doing something completely ordinary. Extraordinary.","returning":"Cheese! I see you have continued being a duck. Excellent data.","opening":"I have named the beetle Percy. Peer review may object.","main":"Nature wastes nothing. Except my entire afternoon when a caterpillar is interesting.","story":"I followed a trail for hours. It was my own dropped sandwich.","personal":"Small things deserve witnesses. Somebody should notice how hard they try.","activity":"Sit very still with me. We are about to become part of the scenery.","gift":"A specimen! Or a present. Both? How wonderfully efficient.","farewell":"Percy is leaving. I should see him safely across this enormous twig."},"rare":false},"friend:curie":{"id":"friend:curie","name":"Curie","archetype":"scholarly","species":"duck","shape":"pocket","head":"wedge","palette":["#a0b7c5","#d8d4df","#b8d18b"],"gear":["glasses_nerd"],"prop":"flasks","habit":"Compares two softly fizzing flasks and shields the smaller one from the wind.","bio":"A compact slate duck with a pointed crest, oversized sleeves and patient, mischievous eyes.","height":68,"pace":3.6,"social":0.45,"radius":9,"voice":{"greeting":"Hello, Cheese. Nothing in these bottles is supposed to explode.","returning":"I brought the quiet experiment today. The noisy one has been grounded.","opening":"That green glow is algae. The dramatic lighting was my idea.","main":"Safety goggles make every cup of tea feel like a discovery.","story":"I once spent a week identifying a mysterious powder. It was flour. Excellent flour.","personal":"The best part of a discovery is finding someone who wants to see it.","activity":"Hold this label. If the bottle changes color, look impressed.","gift":"For my collection? Oh, I am going to be unbearable about this.","farewell":"Keep curious, Cheese. Keep your beak out of unlabelled jars."},"rare":false},"friend:picasso":{"id":"friend:picasso","name":"Picasso","archetype":"artistic","species":"duck","shape":"shaggy","head":"swept","palette":["#d5be9e","#b5ccd0","#de937d"],"gear":["hat_beret"],"prop":"brush","habit":"Measures the horizon with a paintbrush, then paints a tiny moustache in the air.","bio":"A wiry, paint-spattered duck with a slanted crest and a beret permanently on the verge of escape.","height":79,"pace":4.1,"social":0.45,"radius":13,"voice":{"greeting":"Do not move, Cheese. You look wonderfully inconvenienced.","returning":"Ah! My favorite difficult subject returns.","opening":"I painted the pond blue. Critics called it accurate. Devastating.","main":"Art should ask questions. Mine mostly asks where I put the brush.","story":"A painting sold once. The buyer thought it was a map. They are probably still lost.","personal":"I make jokes about the work because saying I care is a bit terrifying.","activity":"Pick a color. Any color. I will disagree affectionately.","gift":"What a shape! What a texture! What an excellent friend!","farewell":"Stay interesting. A completely unreasonable thing to ask of a duck."},"rare":false},"friend:frida":{"id":"friend:frida","name":"Frida","archetype":"artistic","species":"duck","shape":"pear","head":"curly","palette":["#b58f77","#d5b994","#e2a39f"],"gear":["flower_lei"],"prop":"pressed_flower","habit":"Tucks a flower behind her crest and presses another carefully into a journal.","bio":"A warm russet duck with heavy brows, a flowering crown and a patient, fearless stare.","height":82,"pace":3.1,"social":0.45,"radius":9,"voice":{"greeting":"There you are. The pond was getting too polite without you.","returning":"I saved a page for you. Try not to eat it.","opening":"That weed has more ambition than half the roses I know.","main":"Pretty is nice. Alive is better. Slightly muddy is usually both.","story":"I painted every crack in a broken pot. Now everyone asks where I bought it.","personal":"Some days I make beautiful things. Some days making anything is enough.","activity":"Find me the least perfect flower. That is the one with the story.","gift":"You saw this and thought of me? That is the whole point of presents.","farewell":"Take up space, Cheese. You are allowed."},"rare":false},"friend:leonardo":{"id":"friend:leonardo","name":"Leonardo","archetype":"artistic","species":"duck","shape":"runner","head":"tuft","palette":["#bfa679","#b9c5ae","#d3ad71"],"gear":["glasses_nerd","backpack_tiny"],"prop":"gears","habit":"Winds a little gear train; one stubborn cog spins the wrong way.","bio":"A tall, uncombed tinkerer with rolled sleeves and too many half-finished marvels.","height":94,"pace":3.9,"social":0.45,"radius":12,"voice":{"greeting":"Cheese! I need an opinion and possibly a very small wrench.","returning":"Remember the flying chair? We are calling it a sitting kite now.","opening":"This invention saves time. Building it only took six months.","main":"It is nearly finished. That is my favorite stage. I have forty things there.","story":"I invented a self-stirring soup. It left the bowl and started a new life.","personal":"Finishing things is frightening. While they are unfinished, they can still be perfect.","activity":"Turn this handle. Gently. More gently than that look suggests.","gift":"A component! A treasure! I have already thought of three bad ideas.","farewell":"Back to the workshop. Something in there just became a noise."},"rare":false},"friend:monet":{"id":"friend:monet","name":"Monet","archetype":"artistic","species":"duck","shape":"low","head":"sleepy","palette":["#89a8a0","#cfc6b8","#b0bedb"],"gear":["sun_hat"],"prop":"lily_brush","habit":"Dabs a little watercolor pad, pauses for the light, and nearly nods off.","bio":"A broad, low-slung painter in soft pond colors with an impractically wide hat.","height":70,"pace":2.2,"social":0.45,"radius":7,"voice":{"greeting":"The light is lovely. Please tell it to stay while I find my brush.","returning":"Same pond, different green. You understand.","opening":"I have painted that lily seventeen times. It remains extremely unhelpful.","main":"The secret is to squint until the problem becomes atmosphere.","story":"A frog sat on my palette. Best landscape I made all summer.","personal":"I keep painting here because it never asks me to hurry.","activity":"Watch that reflection with me. We are being productive. Quietly.","gift":"Oh, that color. I will remember this moment when I use it.","farewell":"I shall follow the light. At a very reasonable pace."},"rare":false},"friend:georgia":{"id":"friend:georgia","name":"Georgia","archetype":"artistic","species":"duck","shape":"teardrop","head":"wedge","palette":["#c9ae90","#e3d1ad","#db926a"],"gear":["spring_gardener_hat"],"prop":"watering_can","habit":"Waters one small bloom and checks it from three very serious angles.","bio":"A long, pale desert-colored duck with sharp feathers and surprising gentleness around seedlings.","height":85,"pace":3.4,"social":0.45,"radius":10,"voice":{"greeting":"Look at that flower, Cheese. No, really look. It is showing off.","returning":"I came back to see what opened. You count, by the way.","opening":"People say my flowers are too big. People are standing too far away.","main":"A small thing can take up your whole day if you finally pay attention.","story":"I carried a seed across a mountain. It grew in the pocket before we arrived.","personal":"I do not need a crowded garden. Just a few things I know how to care for.","activity":"Help me water this without giving it a personal monsoon.","gift":"Thank you. I know exactly where this belongs. Beside something loved.","farewell":"Notice something small for me. Then tell me all about it."},"rare":false},"friend:bubbles":{"id":"friend:bubbles","name":"Bubbles","archetype":"playful","species":"duck","shape":"pocket","head":"round","palette":["#e7c991","#ebdcb3","#8dc7d3"],"gear":["bow_tie_pink"],"prop":"bubble_wand","habit":"Blows one enormous bubble, watches it pop, and looks personally betrayed.","bio":"A round butter-yellow duck with tiny feet, enormous cheeks and no ability to whisper exciting news.","height":65,"pace":4.7,"social":0.75,"radius":11,"voice":{"greeting":"CHEESE! I found a bubble with your exact attitude!","returning":"You are back! I saved you some air. It was inside bubbles.","opening":"This bubble is called Gerald. Do not tell the actual Gerald.","main":"If bubbles are free, why am I so emotionally invested?","story":"I tried to take a bubble home. Longest sad walk of my life. Three steps.","personal":"I like things that do not last. Gives you a reason to notice them now.","activity":"Catch one on your beak! No, emotionally does not count.","gift":"FOR ME? Wait. Let me do the delighted face properly.","farewell":"POP! That means goodbye in bubble. Probably."},"rare":false},"friend:giggles":{"id":"friend:giggles","name":"Giggles","archetype":"playful","species":"duck","shape":"barrel","head":"curly","palette":["#c4a4bd","#e0c8c8","#deaa69"],"gear":["party_hat"],"prop":"banana","habit":"Checks both ways before presenting a banana as if it is a priceless violin.","bio":"A lavender, barrel-shaped comedian with corkscrew feathers and catastrophically good timing.","height":79,"pace":4.1,"social":0.8,"radius":8,"voice":{"greeting":"A duck walks into a pond. The pond says, finally, a professional.","returning":"Cheese! New jokes. Same questionable delivery system.","opening":"I am working on a silent joke. The reviews have been quiet.","main":"This banana is my understudy. Excellent peel for the role.","story":"I once made Professor Hoot snort tea. Still my finest academic achievement.","personal":"Making people laugh is how I check they are still there with me.","activity":"You be the straight duck. It will be a terrible strain, I know.","gift":"Oh! A gift with no punchline. Those are my favorite, actually.","farewell":"Thank you, you have been a wonderful pond."},"rare":false},"friend:zippy":{"id":"friend:zippy","name":"Zippy","archetype":"playful","species":"duck","shape":"runner","head":"swept","palette":["#879ebc","#b8d1cc","#efa578"],"gear":["cap_sports"],"prop":"yoyo","habit":"Walks a yo-yo, trips over absolutely nothing, and recovers with a bow.","bio":"A narrow blue blur with a long swept crest, one untied lace and twelve simultaneous plans.","height":78,"pace":6,"social":0.6,"radius":20,"voice":{"greeting":"HiCheesehaveyouseenthis—right. Breathing. Hello.","returning":"I am back! You may not have noticed the middle bit where I left.","opening":"My yo-yo returns more reliably than my attention.","main":"Standing still is just walking very, very badly.","story":"I won a race to the wrong tree. Nobody can take that away from me.","personal":"Sometimes I go fast so nobody notices I am not sure where to go.","activity":"Race you to that reed! Walking race. I am developing range.","gift":"Oh wow. I will cherish this at an appropriate velocity.","farewell":"Bye! Wait, one more—nope, gone!"},"rare":false},"friend:bouncy":{"id":"friend:bouncy","name":"Bouncy","archetype":"playful","species":"duck","shape":"pear","head":"tuft","palette":["#d5ac7d","#ebce94","#d6929b"],"gear":["bunny_slippers"],"prop":"ball","habit":"Bounces a stitched ball, crouches with it, and wobbles after the catch.","bio":"A pear-shaped peach duck with springy knees, fluffy slippers and a solemn devotion to silliness.","height":73,"pace":4.8,"social":0.65,"radius":12,"voice":{"greeting":"Boing. That was my entrance. I rehearsed it.","returning":"Cheese! The ground still works. I checked with my face.","opening":"This ball has a slow leak. We are both learning to pace ourselves.","main":"You cannot be dignified and airborne at the same time. I have tried.","story":"I bounced into a hedge once and came out with a better haircut.","personal":"I practice the easy things until they feel like flying.","activity":"One bounce each. No championship. Just the nice little thump.","gift":"This deserves a happy bounce. Stand clear of the elbows.","farewell":"Land softly, Cheese. Especially after the good bits."},"rare":false},"friend:sunny":{"id":"friend:sunny","name":"Sunny","archetype":"playful","species":"duck","shape":"teardrop","head":"pom","palette":["#d9b47b","#f0d699","#dd987b"],"gear":["flower_lei"],"prop":"pinwheel","habit":"Coaxes a pinwheel with a tiny breath and cheers when the wind takes over.","bio":"A honey-colored duck with a spectacular feather pompadour and optimism that has learned to be patient.","height":80,"pace":3.7,"social":0.7,"radius":12,"voice":{"greeting":"Morning, Cheese! Or afternoon with ambition. Either works.","returning":"There is my favorite little weather system.","opening":"The pinwheel is resting. It has a demanding career.","main":"A bad day can still contain a very good puddle.","story":"I once organized a sunrise party and slept through it. Everyone liked the quiet.","personal":"I am not cheerful all the time. I just leave a little room for it to come back.","activity":"Find the warmest patch of grass with me. Very serious research.","gift":"You have made today noticeably better. Thank you.","farewell":"See you soon. You do not have to smile for me to be glad you are here."},"rare":false},"friend:shadow":{"id":"friend:shadow","name":"Shadow","archetype":"mysterious","species":"duck","shape":"runner","head":"wedge","palette":["#8894ac","#a1b3ba","#a8bd87"],"gear":["cape"],"prop":"shutter_lantern","habit":"Opens a shuttered lantern just a crack and checks whether anyone noticed.","bio":"A tall slate silhouette with a pointed crest; practices ominous entrances and secretly repairs birdhouses.","height":91,"pace":3.3,"social":0.25,"radius":16,"voice":{"greeting":"We meet at last. Again. The wording is difficult after the first time.","returning":"I was never gone. Except briefly, for groceries.","opening":"Every pond has secrets. This one has a surprisingly aggressive shopping list.","main":"I work in the shadows. Mostly because the glare gives me a headache.","story":"Someone left a repaired birdhouse outside your gate. Mysterious. Very mysterious.","personal":"It is easier to do kind things when nobody makes a fuss about them.","activity":"Keep watch. I am performing a covert act of tidying.","gift":"You should not have. I am extremely glad you did. Tell no one.","farewell":"I vanish now. Please ignore the squeaky foot."},"rare":false},"friend:phantom":{"id":"friend:phantom","name":"Phantom","archetype":"mysterious","species":"duck","shape":"barrel","head":"bob","palette":["#ada3bd","#d9ced8","#ccae79"],"gear":["hat_tophat"],"prop":"mask","habit":"Raises a theatre mask, peeks over it, and performs a completely unnecessary bow.","bio":"A broad lilac theatrical duck with a velvet-dark cape and an entrance for every occasion.","height":88,"pace":3,"social":0.4,"radius":10,"voice":{"greeting":"Behold! A visitor! Yes, it is me. The smoke budget was cut.","returning":"The sequel arrives. Critics describe it as much the same duck.","opening":"I am rehearsing a tragic monologue about an empty biscuit tin.","main":"Mystery is ninety percent lighting and ten percent not answering practical questions.","story":"I haunted a shed once. The owner asked if I could help with the shelves.","personal":"The costume helps me say things I am too shy to say as myself.","activity":"You take the dramatic pause. I will handle the dramatic everything else.","gift":"A tribute! Oh. An actual thoughtful present. That is considerably better.","farewell":"Farewell, sweet pond! I will be just behind that tree if you need me."},"rare":false},"friend:enigma":{"id":"friend:enigma","name":"Enigma","archetype":"mysterious","species":"duck","shape":"pocket","head":"brow","palette":["#b5ac8d","#c4c5ad","#a2b9d1"],"gear":["monocle"],"prop":"puzzle","habit":"Turns a little wooden puzzle, solves it, and immediately pretends it is still difficult.","bio":"A square-browed pocket duck in muted olive; asks riddles but cannot keep a birthday secret.","height":65,"pace":3.5,"social":0.35,"radius":9,"voice":{"greeting":"What has two feet and too many questions? Hello.","returning":"You found me. Admittedly I was standing in the usual place.","opening":"I brought a puzzle. The first puzzle is where I put the instructions.","main":"The answer was friendship. Terrible riddle. Excellent answer.","story":"I hid a present so well I had to give the recipient a second present: an apology.","personal":"Not everything needs solving. I am trying to learn that without making it a puzzle.","activity":"Hold this piece. No, that is the whole puzzle. You solved it emotionally.","gift":"How did you know? No, do not tell me. I like this mystery.","farewell":"Until the next question mark, Cheese."},"rare":false},"friend:whisper":{"id":"friend:whisper","name":"Whisper","archetype":"mysterious","species":"duck","shape":"low","head":"sleepy","palette":["#b5bbb7","#ddd9cf","#a1c1b2"],"gear":["scarf_winter"],"prop":"listening_shell","habit":"Leans toward a shell, answers with one quiet syllable, and folds the scarf closer.","bio":"A small, long-bodied pearl-gray duck who collects pond sounds and never mistakes quiet for empty.","height":64,"pace":2.3,"social":0.3,"radius":6,"voice":{"greeting":"Hello, Cheese. I brought a quiet sort of hello.","returning":"I recognized your footsteps. One determined little scuff.","opening":"That reed makes a different sound when rain is coming.","main":"You can sit without talking. I am very good at the other half of that conversation.","story":"I recorded the dawn once. Mostly it was my own stomach.","personal":"People talk over quiet things. Thank you for not doing that to me.","activity":"Listen. There is a tiny sound hiding under the large one.","gift":"Oh. You listened when I mentioned it. I will remember that.","farewell":"I will leave the quiet with you. There is plenty."},"rare":false},"friend:raven":{"id":"friend:raven","name":"Raven","archetype":"mysterious","species":"duck","shape":"teardrop","head":"swept","palette":["#82919e","#a0aabd","#ce9eaa"],"gear":["masquerade_mask"],"prop":"quill","habit":"Writes one brooding line, crosses it out, and adds a tiny smiling duck.","bio":"An ink-blue duck with a razor crest and a poet’s solemn face; writes secretly terrible limericks.","height":87,"pace":3.6,"social":0.3,"radius":13,"voice":{"greeting":"The pond broods. I brood. You appear to be looking for lunch.","returning":"Another chapter. Same questionable protagonist. I mean me.","opening":"I am writing about the abyss. It is the deep bit beside the dock.","main":"Nothing rhymes with orange. A personal attack on my sunset poem.","story":"My darkest poem was used to wrap a sandwich. The reader said it was moving.","personal":"I write down ordinary days because losing them frightens me a little.","activity":"Give me a word, Cheese. Preferably one with a manageable number of syllables.","gift":"I shall commemorate this in verse. You may request the short version.","farewell":"May your night contain only the interesting kind of darkness."},"rare":false},"friend:charity":{"id":"friend:charity","name":"Charity","archetype":"generous","species":"duck","shape":"barrel","head":"curly","palette":["#c4a592","#e0c4a5","#b0bfa4"],"gear":["scarf_striped"],"prop":"sewing","habit":"Mends a tiny sock, holds it up to the light, and discovers a second hole.","bio":"A broad, cinnamon-seamed duck with a knitting basket and an inability to leave a loose button alone.","height":83,"pace":2.8,"social":0.75,"radius":8,"voice":{"greeting":"Hello, love. Hold still. Your imaginary button is loose.","returning":"There you are. I made too much again. A mysterious recurring accident.","opening":"I knit while I think. You can tell the difficult thoughts by the lumpy bits.","main":"A patch is a thing deciding it is not finished being useful.","story":"I made a scarf for a snake once. We had to discuss where the neck ended.","personal":"I am learning to let people help me too. Turns out that is part of kindness.","activity":"Keep me company while I fix this. Company counts as helping.","gift":"For me? Sit down. I need a moment to be looked after.","farewell":"Be kind to yourself, Cheese. I cannot be everywhere."},"rare":false},"friend:grace":{"id":"friend:grace","name":"Grace","archetype":"generous","species":"duck","shape":"runner","head":"bob","palette":["#a9b9bc","#e5d8c5","#c4a5c9"],"gear":["pearl_necklace"],"prop":"tea_cup","habit":"Balances a teacup, corrects her posture, and quietly rescues a spilled drop.","bio":"A tall pearl duck with immaculate feathers and the diplomatic skill to call chaos a lively afternoon.","height":95,"pace":2.9,"social":0.65,"radius":8,"voice":{"greeting":"Cheese, darling. What a beautifully assertive mess.","returning":"I hoped I would find you here. I brought the good cups.","opening":"Etiquette is mostly making sure nobody feels foolish. The tiny spoon is optional.","main":"I do not gossip. I provide context with excellent refreshments.","story":"I hosted a formal tea during a thunderstorm. We drank from the rain-filled cups.","personal":"Being composed is not the same as being fine. I appreciate when you ask.","activity":"Tea? You may hold the cup however your wings manage.","gift":"How thoughtful. I shall use it, not save it for a mythical better day.","farewell":"Look after your little corner of the world, darling."},"rare":false},"friend:blessing":{"id":"friend:blessing","name":"Blessing","archetype":"generous","species":"duck","shape":"pear","head":"round","palette":["#acb991","#d4d5b7","#dca387"],"gear":["spring_flower_crown"],"prop":"sprout","habit":"Shelters a seedling in both wings and turns it gently toward the light.","bio":"A soft sage-green duck with round cheeks, soil under the feathers and fierce faith in second chances.","height":77,"pace":3,"social":0.6,"radius":9,"voice":{"greeting":"Good to see you growing, Cheese. Even sideways counts.","returning":"Your little patch has changed. So have you. Both quietly.","opening":"This seedling was marked unlikely. I dislike that sort of label.","main":"Compost is a second chance with a very distinctive smell.","story":"I planted a whole bed upside down once. The plants sorted me out.","personal":"I keep things alive because somebody once did that for me on a hard day.","activity":"Let us give this small thing a better place to begin.","gift":"I will take good care of it. You can come and check.","farewell":"See you soon. Drink some water. Yes, standing in it is different."},"rare":false},"friend:angel":{"id":"friend:angel","name":"Angel","archetype":"generous","species":"duck","shape":"pocket","head":"tuft","palette":["#c0cbcf","#e9e0ce","#d7a095"],"gear":["bow_tie_blue"],"prop":"first_aid","habit":"Checks a little first-aid tin and applies a plaster to a scuffed toy.","bio":"A tiny cloud-white duck with one feather sticking up and the stern tenderness of a village nurse.","height":62,"pace":3.9,"social":0.8,"radius":7,"voice":{"greeting":"Hello, Cheese. Any scrapes, worries, or suspiciously brave faces?","returning":"Good, you are here. I can stop pretending I was not checking.","opening":"This plaster has a star on it. Medically essential, obviously.","main":"Rest is not a prize you earn by falling over first.","story":"I once bandaged a scarecrow. He looked like he needed someone to fuss.","personal":"I worry because I care. I am practicing doing the second part without so much first part.","activity":"Sit with me a moment. That is the entire prescription.","gift":"You took care of me. Oh. That is a rather lovely feeling.","farewell":"No heroic nonsense until after a snack."},"rare":false},"friend:heart":{"id":"friend:heart","name":"Heart","archetype":"generous","species":"duck","shape":"teardrop","head":"pom","palette":["#c79a9d","#e5bfc0","#c4a77a"],"gear":["heart_glasses"],"prop":"letter","habit":"Seals a letter, hesitates, and adds one more tiny heart to the envelope.","bio":"A rose-colored duck with a soft quiff, an oversized satchel and handwritten notes for everyone.","height":81,"pace":3.6,"social":0.85,"radius":10,"voice":{"greeting":"Cheese! I wrote you a note. Then remembered I could just come say it.","returning":"I kept the last nice thing you said. It fits in a very small envelope.","opening":"I put too many stamps on letters so they feel encouraged.","main":"A love letter can just say I saved you the good seat.","story":"I mailed a letter to myself once. It was surprisingly nice to receive.","personal":"I worry people do not know they matter. So I tell them. Sometimes twice.","activity":"Help me think of something kind to write that is not unbearably mushy.","gift":"Oh, you absolute sweetheart. I will be sentimental about this forever.","farewell":"You matter, Cheese. There. Delivered in person."},"rare":false},"friend:cookie":{"id":"friend:cookie","name":"Cookie","archetype":"foodie","species":"duck","shape":"barrel","head":"round","palette":["#c99d75","#e4c49c","#ba9dce"],"gear":["hat_chef"],"prop":"cookie_tray","habit":"Offers a tray, counts the biscuits, and notices a suspiciously beak-shaped gap.","bio":"A flour-dusted round baker with oven-mitt wings and a laugh like a warm kitchen.","height":85,"pace":3,"social":0.7,"radius":8,"voice":{"greeting":"Fresh batch, Cheese. Quality control was ruthless. There are two left.","returning":"I know that look. Yes, I brought them.","opening":"A recipe is a suggestion written by someone who was not hungry enough.","main":"These are rustic. That means I dropped the tray and kept my confidence.","story":"My first cake was a doorstop. Excellent at that, honestly.","personal":"Feeding someone is easier than saying I am glad they exist. Both count.","activity":"Taste this and be honest. Kindly honest. I have feelings and a rolling pin.","gift":"For the kitchen? Or for me? Oh, both. Lovely.","farewell":"Eat something proper later. Yes, more biscuits was your argument last time."},"rare":false},"friend:biscuit":{"id":"friend:biscuit","name":"Biscuit","archetype":"foodie","species":"duck","shape":"low","head":"small","palette":["#bda785","#d8c4a3","#c89f6d"],"gear":["beanie_striped"],"prop":"jam","habit":"Unscrews a jam jar, tastes one careful dab, and screws it shut with great resolve.","bio":"A short, long-backed toasted-brown duck with a tiny cap and the patience of a properly brewed cup.","height":63,"pace":2.5,"social":0.5,"radius":7,"voice":{"greeting":"All right, Cheese? Sit down. Nothing urgent survives a good snack.","returning":"Same time, same crumbs. That is a tradition now.","opening":"I have strong opinions about jam. I am sparing you most of them.","main":"Crunch is a mood. Crumble is a lifestyle.","story":"I once entered a baking contest by accident. I was looking for the queue to eat.","personal":"Familiar things help on unfamiliar days. I like being one of your familiar things.","activity":"We could share this. I have calculated a generous division. Twice.","gift":"Ah, you know me. That is better than the actual present. Almost.","farewell":"Keep a crumb for later. Future you is usually hungry."},"rare":false},"friend:truffle":{"id":"friend:truffle","name":"Truffle","archetype":"foodie","species":"duck","shape":"shaggy","head":"brow","palette":["#a29185","#c6b69d","#ba9c83"],"gear":["autumn_leaf_crown"],"prop":"mushroom_basket","habit":"Sniffs a mushroom basket, rejects a leaf, then sniffs the leaf just in case.","bio":"A shaggy earth-colored forager with a low brow and the solemnity of a tiny woodland detective.","height":78,"pace":3.2,"social":0.35,"radius":16,"voice":{"greeting":"Something smells interesting. Could be lunch. Could be that boot.","returning":"Cheese. I remembered your scent. Pond, attitude, faint bread.","opening":"This mushroom is for looking at. I am fond of staying alive.","main":"A good nose finds dinner. A good brain asks a second opinion.","story":"I tracked a magnificent aroma for a mile. It was my own lunch bag.","personal":"The woods are quieter with company. Not silent-quiet. Safe-quiet.","activity":"Come forage with me. We can admire everything and eat only the sensible bits.","gift":"That is worth a proper sniff. High praise, in my family.","farewell":"Follow your nose. Ask your brain before biting."},"rare":false},"friend:pepper":{"id":"friend:pepper","name":"Pepper","archetype":"foodie","species":"duck","shape":"runner","head":"wedge","palette":["#a98981","#c2a092","#df9a72"],"gear":["bandana"],"prop":"pepper_mill","habit":"Grinds one dramatic twist of pepper, sneezes, and blames the weather.","bio":"A sharp little russet runner with pointed feathers, rolled cuffs and unreasonable confidence in seasoning.","height":80,"pace":4.5,"social":0.6,"radius":12,"voice":{"greeting":"Needs pepper. Hello, Cheese. That applies to the conversation too.","returning":"Back for another serving of my delightful personality?","opening":"A pinch means whatever you can defend afterward.","main":"Bland is not a flavor. It is a cry for help.","story":"I overspiced a soup once. We used it to settle a neighborhood argument.","personal":"I talk loudly when I care. I am learning the difference between flavor and volume.","activity":"Taste and advise. You may swear. It is useful feedback.","gift":"Oh, you know how to season a friendship. Nicely done.","farewell":"Stay sharp. Drink water. Ignore my advice about chili quantities."},"rare":false},"friend:ginger":{"id":"friend:ginger","name":"Ginger","archetype":"foodie","species":"duck","shape":"pear","head":"curly","palette":["#d4a079","#e1bf92","#b5c597"],"gear":["scarf_winter"],"prop":"teapot","habit":"Warms a little teapot between her wings and watches the steam make a spiral.","bio":"A ginger pear-shaped duck with soft curls, oversized scarf ends and an emergency remedy for everything.","height":76,"pace":2.7,"social":0.7,"radius":8,"voice":{"greeting":"Come in, Cheese. Figuratively. We are both already outside.","returning":"I had a feeling you could use something warm.","opening":"This tea fixes almost everything. For the rest, there is sitting together.","main":"Steep for three minutes. Worrying at the pot does not make it faster.","story":"I invented a calming tea so effective I slept through the naming ceremony.","personal":"I learned to make comfort when I could not always find it.","activity":"Hold your cup in both wings. There. That is already a little better.","gift":"What a warm little thought. I will keep it close.","farewell":"Go gently. The world is not improved by you rushing your tea."},"rare":false},"friend:dash":{"id":"friend:dash","name":"Dash","archetype":"athletic","species":"duck","shape":"runner","head":"small","palette":["#9aab92","#c4cba9","#db9e6e"],"gear":["cap_sports"],"prop":"stopwatch","habit":"Times a stretch, checks the result, and rounds it down with a guilty glance.","bio":"A lean green runner with a small neat head and a stopwatch that is suspiciously generous to its owner.","height":86,"pace":5.6,"social":0.5,"radius":19,"voice":{"greeting":"Cheese! Personal best on the way here. In the visiting-a-friend category.","returning":"You ready? Good. Neither am I. Excellent starting conditions.","opening":"I time everything. Except tea. Tea deserves privacy.","main":"Resting heart rate? Very competitive. I am winning at sitting.","story":"I trained for a marathon and accidentally entered a picnic. Best recovery day ever.","personal":"I like having a finish line. Real life is annoyingly vague about those.","activity":"One lap together. Your pace. I can learn something.","gift":"A gift! I have no metric for this. Feels like a record, though.","farewell":"See you on the next lap. Or at the snack table."},"rare":false},"friend:sprint":{"id":"friend:sprint","name":"Sprint","archetype":"athletic","species":"duck","shape":"teardrop","head":"swept","palette":["#a99285","#bfc5b5","#d7ba78"],"gear":["bandana"],"prop":"laces","habit":"Reties one enormous shoelace, tests it with a quick step, and reties the other.","bio":"A low aerodynamic duck whose determined crest points forward while the rest of him is already leaving.","height":77,"pace":6.2,"social":0.45,"radius":21,"voice":{"greeting":"Quick hello, Cheese. Actually, no. Proper hello. I am practicing.","returning":"Came the long way. It had fewer things I had already run past.","opening":"These knots are aerodynamic. They also refuse to stay tied.","main":"There is fast, and there is knows-where-the-hell-they-are-going. I have one.","story":"I once outran a thunderstorm. Then waited in it because my friend was behind.","personal":"Going slower for somebody is not losing. Took me a while to get that.","activity":"Race to the next reed? Winner helps the other one find their breath.","gift":"You thought of me while I was busy thinking about speed. Thank you.","farewell":"Catch you later. Not a challenge. Unless you want it to be."},"rare":false},"friend:champion":{"id":"friend:champion","name":"Champion","archetype":"athletic","species":"duck","shape":"barrel","head":"pom","palette":["#b7a075","#d2bd93","#c7b875"],"gear":["bandana"],"prop":"trophy","habit":"Polishes a cracked trophy and turns the crack proudly toward the light.","bio":"A broad-chested golden duck with a heroic quiff and a trophy earned by finishing last with someone else.","height":94,"pace":3.8,"social":0.75,"radius":12,"voice":{"greeting":"Cheese! Good effort existing today. Strong fundamentals.","returning":"There is the team. All two of us. Formidable.","opening":"The trophy is cracked. That is where the extra character gets in.","main":"A champion thanks the duck who carried the water.","story":"My favorite medal is for a race I did not win. I stopped to help someone finish.","personal":"I was not always confident. Sometimes the loud encouragement is for me too.","activity":"Show me your best terrible stretch. Nobody is getting judged.","gift":"This goes on the shelf with the important wins.","farewell":"Proud of you. You do not need a reason every time."},"rare":false},"friend:victor":{"id":"friend:victor","name":"Victor","archetype":"athletic","species":"duck","shape":"pear","head":"brow","palette":["#a1a9b8","#c5c9cc","#d9a17b"],"gear":["glasses_nerd"],"prop":"clipboard","habit":"Checks a training clipboard, whistles silently, and adds a snack break.","bio":"A sturdy gray coach with heavy eyebrows, a whistle and a schedule containing suspiciously generous rests.","height":84,"pace":3.4,"social":0.6,"radius":11,"voice":{"greeting":"Morning assessment: you are a duck. Promising start.","returning":"Good attendance, Cheese. I have drawn a little star.","opening":"I scheduled spontaneity for later. We may move it forward if necessary.","main":"Hydrate, stretch, complain. In that order, ideally.","story":"I coached a snail once. Tremendous commitment. We are still on the warm-up.","personal":"I make plans because surprises used to scare me. Nice ones still catch me out.","activity":"Try one small improvement. Then we will celebrate a frankly disproportionate amount.","gift":"This was not on the schedule. I am making room for it immediately.","farewell":"Rest is on the plan. Do not make me underline it."},"rare":false},"friend:rocket":{"id":"friend:rocket","name":"Rocket","archetype":"athletic","species":"duck","shape":"pocket","head":"tuft","palette":["#a2b8bf","#ced7c1","#e18c6a"],"gear":["space_helmet"],"prop":"rocket","habit":"Counts down on tiny toes, crouches for takeoff, then gives the ground a skeptical look.","bio":"A compact blue daredevil with a huge helmet and plans that exceed the available duck.","height":69,"pace":5.2,"social":0.6,"radius":17,"voice":{"greeting":"Three, two, one—hello! Still working on the launch part.","returning":"Mission control, I have returned with dirt on my face.","opening":"The helmet is for safety. Also, I sound magnificent inside it.","main":"Gravity is a very persistent heckler.","story":"I built a rocket from reeds. It became an excellent whistle. Flexible objectives.","personal":"I want to do something big. I am learning small brave things count first.","activity":"Be mission control? Tell me when my idea becomes a bad idea.","gift":"Oh! Official mission equipment. You are on the crew forever.","farewell":"To infinity! Or just past the bench. We will assess conditions."},"rare":false},"friendly_goose":{"id":"friendly_goose","name":"Gerald the Goose","archetype":"rare","species":"goose","shape":"goose","head":"goose","palette":["#c6c8b4","#ece5cf","#d89667"],"gear":["bandana"],"prop":"bread_bag","habit":"Patrols with a proud long-necked march, puffs his chest, then offers an embarrassingly small loaf.","bio":"A lanky neighborhood watch goose. Loud enough to be a landmark; soft enough to escort a beetle across a path.","height":106,"pace":3.6,"social":0.5,"radius":18,"voice":{"greeting":"HONK! Neighborhood inspection. You look suspiciously excellent.","returning":"Gerald returns! The pond has passed its preliminary honk assessment.","opening":"Gerald brought a loaf. It used to be larger. Travel is hungry work.","main":"A goose must protect the little ones. Also the picnic. Especially both together.","story":"Gerald once chased his own reflection out of a puddle. Very effective policing.","personal":"Butterflies make Gerald nervous. So much confidence. So little goose.","activity":"Come patrol with Gerald. We will check on everybody and pretend it is official.","gift":"For Gerald? HONK. That was the quiet emotional honk.","farewell":"Gerald is needed elsewhere. Probably. Keep being worth a loud entrance."},"rare":true},"wise_owl":{"id":"wise_owl","name":"Professor Hoot","archetype":"rare","species":"owl","shape":"owl","head":"owl","palette":["#b7a28a","#e1d1b6","#c2abdb"],"gear":[],"prop":"book","habit":"Shuffles a feathered wing, turns a page with a talon and peers over crooked spectacles.","bio":"A tuft-eared owl in a frayed academic shawl. Knows everything except where he left the bookmark.","height":97,"pace":2.5,"social":0.5,"radius":8,"voice":{"greeting":"Hoo. I have brought wisdom. And a book to check whether it is correct.","returning":"My dear Cheese. Still asking difficult questions by merely existing.","opening":"These spectacles are for reading. The second pair is for finding the first.","main":"A footnote is where an author hides a second, less supervised author.","story":"I once lectured a tree stump for twenty minutes. Excellent listener. Poor notes.","personal":"Knowing a great deal does not stop you feeling foolish. It gives the feeling better vocabulary.","activity":"Turn the page with me. Slowly. There is a pressed biscuit in chapter four.","gift":"How thoughtful. I shall write your name inside. In the good handwriting.","farewell":"Remember to question authority. Particularly if it is wearing my hat."},"rare":true},"lost_duckling":{"id":"lost_duckling","name":"Pip the Duckling","archetype":"rare","species":"duckling","shape":"pocket","head":"small","palette":["#e1c995","#eddda7","#d79c92"],"gear":["scarf_red"],"prop":"plush","habit":"Takes three brave little steps, looks back for Cheese, and hugs a lopsided toy frog.","bio":"A tiny fluffy duckling with an oversized knitted scarf and a toy frog that is braver than he is.","height":52,"pace":4.8,"social":0.5,"radius":5,"voice":{"greeting":"Hi. My frog says this pond is safe. Is he right?","returning":"Cheese! I found you without getting lost! Well. Only a tiny bit.","opening":"This is Captain Ribbit. He is in charge of being brave when I am tired.","main":"I practiced a big quack. It came out as a squeak with plans.","story":"I walked all the way to the tall reed by myself. Somebody should put up a sign.","personal":"Can I stay beside you until I remember how to be brave again?","activity":"Watch my little jump? Captain Ribbit is watching too, but he is biased.","gift":"For me? Captain says thank you. I say it louder. THANK YOU.","farewell":"Bye, Cheese. I know the way back now. That is my favorite thing to know."},"rare":true},"traveling_merchant":{"id":"traveling_merchant","name":"Marco the Merchant","archetype":"rare","species":"duck","shape":"barrel","head":"longbill","palette":["#bd936f","#c9b889","#c398c7"],"gear":["hat_tophat"],"prop":"case","habit":"Sets down a many-pocketed case, snaps it open and polishes one absolutely ordinary pebble.","bio":"A squat traveling salesman with a battered stovepipe hat, striped waistcoat and a fondness for hopeless bargains.","height":85,"pace":2.8,"social":0.5,"radius":11,"voice":{"greeting":"Cheese! Fine wares, questionable provenance, impeccable customer service.","returning":"My favorite customer! A statement I make to very few ducks at once.","opening":"This pebble is unique. So is every pebble. I prefer not to mention the second bit.","main":"The price includes a story. The story may include further prices.","story":"I sold a hole once. The buyer wanted somewhere to put a fence post. Honest business.","personal":"I remember every place that lets me sit down without asking what I am selling.","activity":"Have a look. You do not have to buy anything. That bit is sincere.","gift":"A gift with no invoice? You are making me reconsider my entire profession.","farewell":"May your pockets be full and your regrets reasonably priced."},"rare":true},"celebrity_duck":{"id":"celebrity_duck","name":"Sir Quackington III","archetype":"rare","species":"duck","shape":"runner","head":"pom","palette":["#b7b7ca","#e3d6bc","#dbad70"],"gear":["hat_crown","cape"],"prop":"rose","habit":"Sweeps a velvet cape into a grand bow, checks for an audience, then smiles shyly when noticed.","bio":"An elegant, long-necked actor with an extravagant crown, a battered rehearsal rose and very ordinary stage fright.","height":100,"pace":2.9,"social":0.5,"radius":10,"voice":{"greeting":"Your pond is graced by—oh, it is you, Cheese. May I just sit for a minute?","returning":"The triumphant return! Slightly less triumphant knees today.","opening":"This crown is heavier than my entire first apartment. It was a bucket.","main":"Applause is lovely. Someone remembering how you take your tea is better.","story":"My first audience was three frogs. Two left. The third was a stone.","personal":"Sometimes I worry they love the feathers and not the duck inside them.","activity":"Rehearse a bow with me? Yours may contain more contempt. It is a valid interpretation.","gift":"For the actual me? Oh. That is unexpectedly moving.","farewell":"Until we meet again. No fanfare necessary. A little would be nice."},"rare":true},"mysterious_crow":{"id":"mysterious_crow","name":"Corvus the Crow","archetype":"rare","species":"crow","shape":"crow","head":"crow","palette":["#929bac","#b3bfd1","#c4ad7c"],"gear":[],"prop":"buttons","habit":"Hops sideways, checks a button collection and hides the shiniest one under a patched wing.","bio":"A scruffy charcoal crow with one bent tail feather, silver buttons and the manners of a suspicious antique dealer.","height":83,"pace":4.4,"social":0.5,"radius":16,"voice":{"greeting":"Nice pond. Anything shiny here legally unattended?","returning":"Cheese. I returned the spoon. A spoon. Let us not dwell on details.","opening":"This button has history. Mostly being a button, but it did that very well.","main":"I do not steal. I relocate things into a more appreciative social environment.","story":"I once traded a ring for a sandwich. Best investment of my life. Terrible resale value.","personal":"I bring you odd little things because I am not very good at bringing myself.","activity":"Judge these buttons. Be cruel. They need honest criticism.","gift":"You picked this for me? I will hide it somewhere better than the others.","farewell":"Keep one eye on the sky. And one on the cutlery."},"rare":true},"butterfly_fairy":{"id":"butterfly_fairy","name":"Flutter","archetype":"rare","species":"butterfly","shape":"butterfly","head":"butterfly","palette":["#b8a2cc","#e8c5d7","#aad5bc"],"gear":[],"prop":"pollen","habit":"Hovers in little figure-eights, fans patterned wings and shakes pollen from one offended antenna.","bio":"A tiny theatrical pollinator with lace-edged wings, mismatched antenna curls and strong opinions about flowers.","height":66,"pace":4.6,"social":0.5,"radius":18,"voice":{"greeting":"Darling, your air is lovely. A little humid. Very flattering to the wings.","returning":"Cheese! I followed the flowers. Then the unmistakable atmosphere of you.","opening":"This pollen is everywhere. I am a magical being and also a lint problem.","main":"Metamorphosis is glamorous after the bit where you become soup.","story":"I once landed on a painted flower. Charming conversation. Terrible refreshments.","personal":"Being delicate does not mean I have not survived a very strange amount.","activity":"Hold still. You have a speck of ordinary on you. There, improved.","gift":"Oh! I shall make room in my impossibly small luggage.","farewell":"Bloom outrageously, Cheese. Even if it annoys someone."},"rare":true},"grumpy_toad":{"id":"grumpy_toad","name":"Grumble the Toad","archetype":"rare","species":"toad","shape":"toad","head":"toad","palette":["#9fa47c","#c1bd93","#c1a07b"],"gear":[],"prop":"mug","habit":"Settles his broad belly, sips from a chipped acorn mug and performs one profoundly dissatisfied hop.","bio":"A squat, wart-speckled toad with heavy lids and a hand-knitted vest he claims to hate but never removes.","height":66,"pace":2.7,"social":0.5,"radius":7,"voice":{"greeting":"Hmph. Moved my nice damp rock. By which I mean I moved. Still annoying.","returning":"You again. Good. Someone sensible to complain near.","opening":"This mug says cheerful. I have registered a complaint with the acorn.","main":"Too sunny for a drizzle. Too dry for a proper misery. Make up your mind, weather.","story":"Someone knitted me this vest. It is hideous. Touch it and lose a finger.","personal":"I come here because you do not tell me to cheer up. Makes me almost cheerful.","activity":"Sit. We can dislike the same cloud. Efficient use of company.","gift":"Hmph. That is... annoyingly thoughtful. Thank you. Once.","farewell":"I am leaving. Do not make it a thing. Save my damp bit."},"rare":true}};
